from dataclasses import dataclass

@dataclass(frozen=True)
class Principal:

    user_id: str
    tenant_id: str
    permissions: frozenset[str]

@dataclass(frozen=True)
class Delegation:

    tenant_id: str
    agent_id: str
    permissions: frozenset[str]
    allowed_resources: frozenset[str]

@dataclass(frozen=True)
class Resource:

    resource_id: str
    tenant_id: str

def authorize(
    principal,
    delegation,
    resource,
    operation
):

    if not (
        principal.tenant_id
        == delegation.tenant_id
        == resource.tenant_id
    ):
        raise PermissionError(
            "Tenant mismatch"
        )

    if operation not in principal.permissions:
        raise PermissionError(
            "Principal lacks permission"
        )

    if operation not in delegation.permissions:
        raise PermissionError(
            "Outside delegated scope"
        )

    if (
        resource.resource_id
        not in delegation.allowed_resources
    ):
        raise PermissionError(
            "Resource outside task scope"
        )

    return True

principal = Principal(
    user_id="employee_1",
    tenant_id="tenant_a",
    permissions=frozenset({
        "budget.read"
    })
)

delegation = Delegation(
    tenant_id="tenant_a",
    agent_id="finance_agent",
    permissions=frozenset({
        "budget.read"
    }),
    allowed_resources=frozenset({
        "department_101"
    })
)

resource = Resource(
    resource_id="department_101",
    tenant_id="tenant_a"
)

print(authorize(
    principal,
    delegation,
    resource,
    "budget.read"
))

